-- READ-ONLY audit of value provenance for P3 estimate-selection inputs.
-- Target outTemp is absent; endpoint/context history is checked for every filter variable.
WITH role_times AS (SELECT 1556184300 AS event_time, 'LEFT_ENDPOINT' AS event_role UNION ALL SELECT 1556184600, 'TARGET' UNION ALL SELECT 1556184900, 'TARGET' UNION ALL SELECT 1556185200, 'TARGET' UNION ALL SELECT 1556185500, 'RIGHT_ENDPOINT' UNION ALL SELECT 1598788800, 'LEFT_ENDPOINT' UNION ALL SELECT 1598789100, 'TARGET' UNION ALL SELECT 1598789400, 'TARGET' UNION ALL SELECT 1598789700, 'RIGHT_ENDPOINT' UNION ALL SELECT 1603181400, 'LEFT_ENDPOINT' UNION ALL SELECT 1603181700, 'TARGET' UNION ALL SELECT 1603182000, 'TARGET' UNION ALL SELECT 1603182300, 'RIGHT_ENDPOINT' UNION ALL SELECT 1603185300, 'LEFT_ENDPOINT' UNION ALL SELECT 1603185600, 'TARGET' UNION ALL SELECT 1603185900, 'TARGET' UNION ALL SELECT 1603186200, 'RIGHT_ENDPOINT' UNION ALL SELECT 1603188300, 'LEFT_ENDPOINT' UNION ALL SELECT 1603188600, 'TARGET' UNION ALL SELECT 1603188900, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607100300, 'LEFT_ENDPOINT' UNION ALL SELECT 1607100600, 'TARGET' UNION ALL SELECT 1607100900, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607102400, 'LEFT_ENDPOINT' UNION ALL SELECT 1607102700, 'TARGET' UNION ALL SELECT 1607103000, 'TARGET' UNION ALL SELECT 1607103300, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607212500, 'LEFT_ENDPOINT' UNION ALL SELECT 1607212800, 'TARGET' UNION ALL SELECT 1607213100, 'TARGET' UNION ALL SELECT 1607213400, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607215500, 'LEFT_ENDPOINT' UNION ALL SELECT 1607215800, 'TARGET' UNION ALL SELECT 1607216100, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607217000, 'LEFT_ENDPOINT' UNION ALL SELECT 1607217300, 'TARGET' UNION ALL SELECT 1607217600, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607310900, 'LEFT_ENDPOINT' UNION ALL SELECT 1607311200, 'TARGET' UNION ALL SELECT 1607311500, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607314500, 'LEFT_ENDPOINT' UNION ALL SELECT 1607314800, 'TARGET' UNION ALL SELECT 1607315100, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607316900, 'LEFT_ENDPOINT' UNION ALL SELECT 1607317200, 'TARGET' UNION ALL SELECT 1607317500, 'RIGHT_ENDPOINT' UNION ALL SELECT 1607524200, 'LEFT_ENDPOINT' UNION ALL SELECT 1607524500, 'TARGET' UNION ALL SELECT 1607524800, 'TARGET' UNION ALL SELECT 1607525100, 'TARGET' UNION ALL SELECT 1607525400, 'TARGET' UNION ALL SELECT 1607525700, 'RIGHT_ENDPOINT'), filter_variables AS (SELECT 'outTemp' AS variable UNION ALL SELECT 'outHumidity' UNION ALL SELECT 'rain' UNION ALL SELECT 'rainRate' UNION ALL SELECT 'windSpeed')
SELECT rt.event_time,rt.event_role,a.dateTime AS archive_row_present,
       a.usUnits,a.interval,a.outTemp,a.outHumidity,a.rain,a.rainRate,a.windSpeed,
       fv.variable,c.id AS change_id,c.state AS change_state,c.batch_key,
       c.old_value,c.new_value,c.source_database,c.source_time,c.source_value,
       c.reason,c.created_at,c.applied_at
FROM role_times rt CROSS JOIN filter_variables fv
LEFT JOIN loucka_reconstruction.archive a ON a.dateTime=rt.event_time
LEFT JOIN loucka_reconstruction.reconstruction_changes c
 ON c.target_time=rt.event_time AND c.variable=fv.variable
ORDER BY rt.event_time,rt.event_role,fv.variable,c.id;
